-- ============================================
-- 敬語 (Keigo) Seed Data (~50 items)
-- category: 'keigo', subcategory で分類
-- 3カテゴリ: rule(変換規則), mistake(よくある間違い), uchi_soto(ウチ・ソト)
-- ============================================
INSERT INTO it_glossary (term_ja, reading, term_ko, term_en, category, subcategory, description, example_sentence) VALUES

  -- ============================================
  -- 敬語変換規則 (rule) - 20 items
  -- ============================================
  ('する → される / いたす', 'する → される / いたす', '하다 → 하시다(존경) / (제가) 하다(겸양)', 'do → (honorific) do / (humble) do', 'keigo', 'rule', '「する」의 존경어는 「される」, 겸양어는 「いたす」. 상대의 동작에는 「される」, 자신의 동작에는 「いたす」를 사용.', '部長がご説明されます。/ 私がご説明いたします。'),
  ('見る → ご覧になる / 拝見する', 'みる → ごらんになる / はいけんする', '보다 → 보시다(존경) / 배견하다(겸양)', 'see → (honorific) see / (humble) see', 'keigo', 'rule', '「見る」의 존경어는 「ご覧になる」, 겸양어는 「拝見する」. 「拝見」은 한자어로 격식 있는 표현.', 'こちらの資料をご覧になってください。/ 早速拝見いたします。'),
  ('言う → おっしゃる / 申す', 'いう → おっしゃる / もうす', '말하다 → 말씀하시다(존경) / 말씀드리다(겸양)', 'say → (honorific) say / (humble) say', 'keigo', 'rule', '「言う」의 존경어는 「おっしゃる」, 겸양어는 「申す」. 비즈니스에서 가장 자주 사용되는 경어 변환 중 하나.', '部長がおっしゃった通りです。/ 私から一言申し上げます。'),
  ('行く → いらっしゃる / 参る', 'いく → いらっしゃる / まいる', '가다 → 가시다(존경) / 가다(겸양)', 'go → (honorific) go / (humble) go', 'keigo', 'rule', '「行く」의 존경어는 「いらっしゃる」, 겸양어는 「参る」. 「いらっしゃる」는 行く・来る・いる 모두에 사용 가능.', 'お客様が会議室にいらっしゃいます。/ 午後から本社に参ります。'),
  ('来る → いらっしゃる / 参る', 'くる → いらっしゃる / まいる', '오다 → 오시다(존경) / 오다(겸양)', 'come → (honorific) come / (humble) come', 'keigo', 'rule', '「来る」의 존경어도 「いらっしゃる」, 겸양어도 「参る」. 「行く」와 동일한 변환이므로 문맥으로 구분.', 'お客様がいらっしゃいました。/ 明日そちらに参ります。'),
  ('食べる → 召し上がる / いただく', 'たべる → めしあがる / いただく', '먹다 → 드시다(존경) / 먹다(겸양)', 'eat → (honorific) eat / (humble) eat', 'keigo', 'rule', '「食べる」의 존경어는 「召し上がる」, 겸양어는 「いただく」. 「いただく」는 「もらう」의 겸양어로도 사용됨에 주의.', 'どうぞ召し上がってください。/ ありがたくいただきます。'),
  ('知る → ご存じ / 存じる', 'しる → ごぞんじ / ぞんじる', '알다 → 아시다(존경) / 알다(겸양)', 'know → (honorific) know / (humble) know', 'keigo', 'rule', '「知る」의 존경어는 「ご存じ」(형용사적), 겸양어는 「存じる」. 「ご存じですか」는 상대에게, 「存じております」는 자신에게 사용.', 'この件についてご存じですか。/ はい、存じております。'),
  ('聞く → お聞きになる / 伺う', 'きく → おききになる / うかがう', '듣다/묻다 → 들으시다(존경) / 여쭙다(겸양)', 'hear/ask → (honorific) hear / (humble) ask', 'keigo', 'rule', '「聞く」의 존경어는 「お聞きになる」, 겸양어는 「伺う」. 「伺う」는 「訪問する」의 겸양어로도 쓰임.', '部長からお聞きになりましたか。/ 一点伺いたいのですが。'),
  ('読む → お読みになる / 拝読する', 'よむ → およみになる / はいどくする', '읽다 → 읽으시다(존경) / 배독하다(겸양)', 'read → (honorific) read / (humble) read', 'keigo', 'rule', '「読む」의 존경어는 「お読みになる」, 겸양어는 「拝読する」. 「拝読」은 상대의 글을 읽을 때 사용하는 격식체.', 'お時間のある時にお読みになってください。/ メールを拝読いたしました。'),
  ('もらう → — / いただく', 'もらう → — / いただく', '받다 → —(존경 없음) / 받다(겸양)', 'receive → — / (humble) receive', 'keigo', 'rule', '「もらう」에는 존경어가 없고, 겸양어는 「いただく」. 상대로부터 무언가를 받을 때 사용. 「〜していただく」형태로 의뢰 표현에도 활용.', 'ご確認いただけますでしょうか。/ 資料をいただきました。'),
  ('あげる → — / 差し上げる', 'あげる → — / さしあげる', '주다 → —(존경 없음) / 드리다(겸양)', 'give → — / (humble) give', 'keigo', 'rule', '「あげる」의 겸양어는 「差し上げる」. 자신이 상대에게 무언가를 줄 때 사용. 단, 목상에게 「〜してあげる」는 실례.', 'お土産を差し上げます。/ ご連絡を差し上げたいのですが。'),
  ('会う → — / お目にかかる', 'あう → — / おめにかかる', '만나다 → —(존경 없음) / 뵙다(겸양)', 'meet → — / (humble) meet', 'keigo', 'rule', '「会う」의 겸양어는 「お目にかかる」. 격식 있는 자리에서 상대를 만나는 것을 표현할 때 사용.', 'お目にかかれて光栄です。/ 先日お目にかかった件ですが。'),
  ('いる → いらっしゃる / おる', 'いる → いらっしゃる / おる', '있다 → 계시다(존경) / 있다(겸양)', 'be (exist) → (honorific) be / (humble) be', 'keigo', 'rule', '「いる」의 존경어는 「いらっしゃる」, 겸양어는 「おる」. 전화 응대에서 자사 직원의 재실 여부를 알릴 때 「おります」를 사용.', '社長はただいまいらっしゃいません。/ 私は東京におります。'),
  ('思う → お思いになる / 存じる', 'おもう → おおもいになる / ぞんじる', '생각하다 → 생각하시다(존경) / 생각하다(겸양)', 'think → (honorific) think / (humble) think', 'keigo', 'rule', '「思う」의 존경어는 「お思いになる」, 겸양어는 「存じる」. 「存じます」는 자신의 의견을 겸손하게 전달할 때 사용.', 'どのようにお思いになりますか。/ 私もそのように存じます。'),
  ('お/ご〜になる（尊敬語の一般形）', 'お/ご〜になる', 'お/ご~하시다 (존경어 일반형)', 'o/go ~ ni naru (general honorific form)', 'keigo', 'rule', '존경어 일반형 패턴. 和語(일본 고유어)에는 「お」, 漢語(한자어)에는 「ご」를 붙이고 「〜になる」를 접속. 대부분의 동사를 존경어로 변환 가능.', 'こちらの資料をお使いになってください。/ ご確認になりましたか。'),
  ('お/ご〜する（謙譲語の一般形）', 'お/ご〜する', 'お/ご~하다 (겸양어 일반형)', 'o/go ~ suru (general humble form)', 'keigo', 'rule', '겸양어 일반형 패턴. 和語에는 「お」, 漢語에는 「ご」를 붙이고 「〜する/いたす」를 접속. 자신의 동작을 겸손하게 표현.', 'お荷物をお持ちします。/ ご案内いたします。'),
  ('お/ご〜いただく（謙譲語の依頼形）', 'お/ご〜いただく', 'お/ご~해 주시다 (겸양어 의뢰형)', 'o/go ~ itadaku (humble request form)', 'keigo', 'rule', '겸양어 의뢰형 패턴. 상대에게 무언가를 부탁할 때 사용. 「〜していただけますか」보다 더 정중한 표현.', 'ご確認いただけますでしょうか。/ お時間をいただきたいのですが。'),
  ('お/ご〜ください（尊敬語の依頼形）', 'お/ご〜ください', 'お/ご~해 주십시오 (존경어 의뢰형)', 'o/go ~ kudasai (honorific request form)', 'keigo', 'rule', '존경어 의뢰형 패턴. 상대에게 정중하게 요청할 때 사용. 「〜してください」보다 높은 경의를 표현.', 'こちらにお掛けください。/ ご自由にお使いください。'),
  ('です/ます（丁寧語の基本）', 'です/ます', 'です/ます (정중어의 기본)', 'desu/masu (basic polite form)', 'keigo', 'rule', '정중어의 가장 기본적인 형태. 존경어・겸양어와 달리 상대나 자신의 동작에 관계없이 문장 전체를 정중하게 만드는 역할.', '明日は会議があります。/ こちらが報告書です。'),
  ('ございます（丁寧語の最上級）', 'ございます', 'ございます (정중어의 최상급)', 'gozaimasu (most polite form)', 'keigo', 'rule', '「ある/いる」의 정중어 최상급. 「あります」보다 더 격식 있는 표현. 접객이나 공식 장면에서 사용.', 'お手洗いは2階にございます。/ 何かご不明な点はございますか。'),

  -- ============================================
  -- よくある間違い (mistake) - 15 items
  -- ============================================
  ('させていただくの乱用', 'させていただくのらんよう', '~시켜 주시다의 남용', 'Overuse of sasete-itadaku', 'keigo', 'mistake', '「させていただく」는 상대의 허가가 필요한 상황에서만 사용하는 것이 원칙. 불필요한 장면에서의 사용은 과잉 경어로 어색한 인상을 줌. 예: 「休憩させていただきます」(○) vs 「帰らせていただきます」(△ 상황에 따라).', '✕ 資料を拝見させていただきます → ○ 資料を拝見いたします'),
  ('二重敬語', 'にじゅうけいご', '이중경어', 'Double honorifics', 'keigo', 'mistake', '하나의 동사에 존경어 표현을 두 번 겹쳐 사용하는 오류. 「お〜になる」+「〜れる」등의 중복. 정중함을 높이려다 오히려 부자연스러운 일본어가 됨.', '✕ お読みになられる → ○ お読みになる / ✕ おっしゃられる → ○ おっしゃる'),
  ('バイト敬語', 'ばいとけいご', '아르바이트 경어 (잘못된 경어)', 'Part-time job honorifics (incorrect)', 'keigo', 'mistake', '편의점이나 음식점 등에서 퍼진 잘못된 경어 표현. 비즈니스에서 사용하면 교양이 없어 보일 수 있으므로 주의. 「〜になります」「〜のほう」 등이 대표적.', '✕ こちらが資料になります → ○ こちらが資料でございます'),
  ('ら抜き言葉', 'らぬきことば', '「ら」 빠진 말 (구어체 오류)', 'Ra-nuki kotoba (dropped ra)', 'keigo', 'mistake', '가능형에서 「ら」를 빼는 구어체 습관. 「見れる」「食べれる」등. 일상 회화에서는 허용되기도 하지만, 비즈니스 문서나 공식 자리에서는 부적절.', '✕ 見れますか → ○ 見られますか / ✕ 食べれます → ○ 食べられます'),
  ('自分への尊敬語', 'じぶんへのそんけいご', '자신에게 존경어 사용 오류', 'Using honorifics for oneself', 'keigo', 'mistake', '자신의 동작에 존경어를 사용하는 오류. 존경어는 상대의 동작에만, 겸양어는 자신의 동작에만 사용해야 함. 한국어에서는 자신에게도 높임말을 쓸 수 있어 혼동하기 쉬움.', '✕ 私がおっしゃったのは → ○ 私が申し上げたのは'),
  ('お/ごの付け間違い', 'お/ごのつけまちがい', 'お/ご 붙이기 오류', 'Incorrect use of o/go prefix', 'keigo', 'mistake', '외래어나 적절하지 않은 단어에 「お」「ご」를 붙이는 오류. 일반적으로 외래어에는 「お/ご」를 붙이지 않음. 和語에는 「お」, 漢語에는 「ご」가 원칙.', '✕ おコーヒー → ○ コーヒー / ✕ おビール → ○ ビール'),
  ('謙譲語と尊敬語の混同', 'けんじょうごとそんけいごのこんどう', '겸양어와 존경어 혼동', 'Confusing humble and honorific forms', 'keigo', 'mistake', '상대의 동작에 겸양어를, 자신의 동작에 존경어를 사용하는 오류. 경어 체계에서 가장 기본적이면서도 빈번하게 발생하는 실수.', '✕ お客様が参りました → ○ お客様がいらっしゃいました'),
  ('よろしかったでしょうか', 'よろしかったでしょうか', '~괜찮으셨습니까 (과거형 오용)', 'yoroshikatta deshouka (incorrect past tense)', 'keigo', 'mistake', '현재의 확인 사항에 과거형을 사용하는 오류. 바이트 경어의 대표적인 예. 현재 확인할 때는 현재형을 사용해야 함.', '✕ こちらでよろしかったでしょうか → ○ こちらでよろしいでしょうか'),
  ('なるほどですね', 'なるほどですね', '그렇군요 (비격식 추임새)', 'naruhodo desu ne (informal filler)', 'keigo', 'mistake', '「なるほど」에 「ですね」를 붙인 조어. 문법적으로 부자연스럽고, 상사나 고객에게 사용하면 실례. 동의를 표현할 때는 적절한 대체 표현을 사용.', '✕ なるほどですね → ○ おっしゃる通りです / ○ 承知いたしました'),
  ('了解しました → 承知しました', 'りょうかいしました → しょうちしました', '「알겠습니다」의 경어 레벨 오류', 'ryoukai vs shouchi (politeness level error)', 'keigo', 'mistake', '「了解しました」는 동등한 관계에서 사용하는 표현으로, 상사나 고객에게는 부적절. 「承知しました」나 「かしこまりました」가 더 적절.', '✕ 了解しました → ○ 承知しました / ○ かしこまりました'),
  ('すみません vs 申し訳ございません', 'すみません vs もうしわけございません', '「죄송합니다」의 격식 차이', 'sumimasen vs moushiwake gozaimasen', 'keigo', 'mistake', '「すみません」는 일상적인 사과 표현으로 비즈니스에서는 격식이 부족함. 비즈니스 상황에서는 「申し訳ございません」를 사용하는 것이 적절.', '✕ すみません、遅刻しました → ○ 申し訳ございません、遅刻いたしました'),
  ('〜してあげる（目上に使うと失礼）', '〜してあげる', '~해 드리다 (윗사람에게 쓰면 실례)', '~shite ageru (rude to superiors)', 'keigo', 'mistake', '「〜してあげる」는 은혜를 베푸는 뉘앙스가 있어 상사나 고객에게 사용하면 거만한 인상을 줌. 겸양 표현으로 바꿔야 함.', '✕ 部長に教えてあげます → ○ 部長にお伝えいたします'),
  ('ご苦労様です vs お疲れ様です', 'ごくろうさまです vs おつかれさまです', '「수고하셨습니다」의 사용 대상 오류', 'gokurousama vs otsukaresama', 'keigo', 'mistake', '「ご苦労様」는 윗사람이 아랫사람에게 사용하는 표현. 상사에게 사용하면 실례. 동료나 상사에게는 「お疲れ様です」를 사용.', '✕ 部長、ご苦労様です → ○ 部長、お疲れ様です'),
  ('〜でよろしかったですか（過去形の誤用）', '〜でよろしかったですか', '~로 괜찮으셨습니까 (과거형 오용)', '~de yoroshikatta desu ka (past tense error)', 'keigo', 'mistake', '현재 진행 중인 주문이나 확인에 과거형을 사용하는 오류. 일본 서비스업에서 흔히 듣지만 문법적으로 부정확.', '✕ ご注文は以上でよろしかったですか → ○ ご注文は以上でよろしいですか'),
  ('ちょっとお聞きしたいんですけど', 'ちょっとおききしたいんですけど', '좀 여쭤보고 싶은데요 (격식 부족)', 'chotto okiki shitain desu kedo (too casual)', 'keigo', 'mistake', '「ちょっと」「〜んですけど」는 구어적이고 격식이 부족한 표현. 비즈니스에서는 보다 정중한 표현으로 바꿔야 함.', '✕ ちょっとお聞きしたいんですけど → ○ 少々お伺いしたいのですが'),

  -- ============================================
  -- ウチ・ソト切替規則 (uchi_soto) - 15 items
  -- ============================================
  ('社外への上司紹介：敬称脱着', 'しゃがいへのじょうししょうかい：けいしょうだっちゃく', '사외에 상사를 소개할 때: 경칭 탈착', 'Introducing superiors to outsiders: dropping titles', 'keigo', 'uchi_soto', '사외 사람에게 자사 상사를 소개할 때는 경칭(部長, 課長 등)을 이름 뒤에 붙이지 않고, 역할을 먼저 말한 뒤 이름을 호칭 없이 사용. 일본 비즈니스의 가장 중요한 ウチ・ソト 규칙.', '✕ 田中部長をご紹介します → ○ 弊社の部長の田中をご紹介します'),
  ('「うちの部長の田中」vs「田中部長」', 'うちのぶちょうのたなか vs たなかぶちょう', '「우리 부장 다나카」 vs 「다나카 부장님」', '"Our department head Tanaka" vs "Director Tanaka"', 'keigo', 'uchi_soto', '사외(ソト)에서는 「うちの部長の田中」처럼 역할+이름을 호칭 없이 사용. 사내(ウチ)에서는 「田中部長」처럼 이름+역직으로 경칭 사용. 한국어와 달리 사외에서 자사 상사를 높이면 안 됨.', '（社外）うちの部長の田中が申しておりました。/（社内）田中部長がおっしゃっていました。'),
  ('弊社 vs 御社/貴社', 'へいしゃ vs おんしゃ/きしゃ', '폐사 vs 귀사', 'Our company (humble) vs Your company (honorific)', 'keigo', 'uchi_soto', '자사를 가리킬 때는 「弊社」(겸양), 상대 회사를 가리킬 때는 구두로 「御社」, 서면으로 「貴社」를 사용. 「当社」는 중립적 표현으로 사내 문서에 적합.', '弊社のサービスについてご説明いたします。御社のご要望に沿えるよう努力いたします。'),
  ('当部署 vs そちらの部署', 'とうぶしょ vs そちらのぶしょ', '해당 부서(자사) vs 그쪽 부서(상대)', 'Our department vs Your department', 'keigo', 'uchi_soto', '자사 부서를 가리킬 때는 「当部署」(중립) 또는 「弊部署」(겸양), 상대 부서를 가리킬 때는 「そちらの部署」나 「御部署」를 사용.', '当部署で対応いたします。そちらの部署との連携を図りたいと考えております。'),
  ('社内メール vs 社外メールの文体', 'しゃないメール vs しゃがいメールのぶんたい', '사내 메일 vs 사외 메일 문체 차이', 'Internal vs external email style differences', 'keigo', 'uchi_soto', '사내 메일은 「お疲れ様です」로 시작, 비교적 간결한 경어 사용. 사외 메일은 「いつもお世話になっております」로 시작, 격식 높은 경어와 정중한 마무리 필수.', '（社内）お疲れ様です。確認お願いします。/（社外）いつもお世話になっております。ご確認のほどよろしくお願いいたします。'),
  ('電話で自社の人を「おります」と言う', 'でんわでじしゃのひとを「おります」という', '전화에서 자사 직원에 대해 「おります」 사용', 'Using "orimasu" for colleagues on the phone', 'keigo', 'uchi_soto', '전화 응대 시 자사 직원의 재실 여부를 알릴 때 겸양어 「おります」를 사용. 자사 직원은 ウチ이므로 존경어를 쓰지 않음.', '✕ 田中部長はいらっしゃいます → ○ 田中はおります / ○ 田中は席を外しております'),
  ('取引先に尊敬語、自社に謙譲語', 'とりひきさきにそんけいご、じしゃにけんじょうご', '거래처에 존경어, 자사에 겸양어', 'Honorifics for clients, humble for own company', 'keigo', 'uchi_soto', 'ウチ・ソト의 기본 원칙: 거래처(ソト)의 행위에는 존경어, 자사(ウチ)의 행위에는 겸양어를 사용. 이 원칙은 전화, 메일, 대면 모두에 적용.', 'お客様がご確認くださいました。弊社の担当が確認いたしました。'),
  ('「参ります」vs「いらっしゃいます」', '「まいります」vs「いらっしゃいます」', '「가겠습니다」(자사) vs 「가십니다」(타사)', '"mairu" (own company) vs "irassharu" (other company)', 'keigo', 'uchi_soto', '자사 직원의 이동에는 겸양어 「参る」, 타사 직원의 이동에는 존경어 「いらっしゃる」를 사용. 전화 응대에서 가장 빈번하게 나타나는 ウチ・ソト 전환.', '弊社の担当が午後に参ります。/ 御社の田中様がいらっしゃいます。'),
  ('「申します」vs「おっしゃいます」', '「もうします」vs「おっしゃいます」', '「말씀드립니다」(자사) vs 「말씀하십니다」(타사)', '"mousu" (own company) vs "ossharu" (other company)', 'keigo', 'uchi_soto', '자사 직원의 발언에는 겸양어 「申す」, 타사 직원의 발언에는 존경어 「おっしゃる」를 사용. 자사 상사의 발언도 사외에서는 「申しておりました」로 표현.', '弊社の田中が申しておりました。/ 御社の佐藤様がおっしゃっていた件ですが。'),
  ('社外向けに上司を呼び捨てにする', 'しゃがいむけにじょうしをよびすてにする', '사외에서 상사를 호칭 없이 부르기', 'Addressing superiors without titles to outsiders', 'keigo', 'uchi_soto', '사외 사람과 대화할 때 자사 상사는 이름만으로 호칭(呼び捨て). 한국 문화에서는 상사를 항상 높이므로 적응하기 어려운 규칙이지만, 일본에서는 필수적인 비즈니스 매너.', '✕ 田中部長に確認します → ○ 田中に確認いたします（社外向け）'),
  ('「佐藤は席を外しております」', '「さとうはせきをはずしております」', '「사토는 자리를 비우고 있습니다」 (전화 응대)', '"Sato is away from his desk" (phone handling)', 'keigo', 'uchi_soto', '전화에서 자사 직원의 부재를 알리는 정형 표현. 이름만 사용(경칭 없음) + 겸양어 「おります」. 전화 응대의 기본 중 기본.', 'あいにく佐藤は席を外しております。戻り次第、折り返しお電話いたしましょうか。'),
  ('「弊社の担当の鈴木がご説明いたします」', 'へいしゃのたんとうのすずきがごせつめいいたします', '「폐사 담당 스즈키가 설명드리겠습니다」', '"Our representative Suzuki will explain"', 'keigo', 'uchi_soto', '사외에서 자사 담당자를 소개할 때의 정형 표현. 「弊社」+역할+이름(경칭 없음)+겸양어의 조합. 한 문장에 ウチ・ソト 원칙이 모두 적용된 모범 표현.', '弊社の担当の鈴木がご説明いたします。ご不明な点がございましたら、何なりとお申し付けください。'),
  ('社内会議 vs 客先での言葉遣い', 'しゃないかいぎ vs きゃくさきでのことばづかい', '사내 회의 vs 고객사에서의 말씨 차이', 'Language switching: internal meeting vs client site', 'keigo', 'uchi_soto', '사내 회의에서는 상사에게 존경어를 사용하지만, 고객 앞에서는 그 상사도 ウチ이므로 겸양어로 전환. 같은 상사에 대해 장면에 따라 경어를 바꿔야 하는 것이 핵심.', '（社内）部長がおっしゃった通りです。/（客先）弊社の部長の田中が申しました通り、対応いたします。'),
  ('ウチの範囲の拡大（部署→会社→グループ）', 'うちのはんいのかくだい', 'ウチ 범위의 확대 (부서→회사→그룹)', 'Expanding the "uchi" boundary', 'keigo', 'uchi_soto', 'ウチ의 범위는 상대에 따라 변동. 타부서 직원과 대화할 때는 자기 부서가 ウチ. 타사와 대화할 때는 자사 전체가 ウチ. 그룹사 외부와 대화할 때는 그룹 전체가 ウチ.', '（他部署に）うちの課の山田が対応します。/（他社に）弊社の山田が対応いたします。'),
  ('お客様の前で同僚を紹介する際のルール', 'おきゃくさまのまえでどうりょうをしょうかいするさいのルール', '고객 앞에서 동료를 소개할 때의 규칙', 'Rules for introducing colleagues to customers', 'keigo', 'uchi_soto', '고객 앞에서 자사 동료를 소개할 때는 직급에 관계없이 이름만 사용(경칭 없음) + 겸양어. 동기나 후배뿐 아니라 상사도 동일한 규칙 적용.', 'こちらが弊社のエンジニアの佐藤でございます。本プロジェクトの技術面を担当しております。');
